const http = require('http');
const { Server } = require('socket.io');
const { createAdapter } = require('@socket.io/redis-adapter');
const { Redis } = require('ioredis');
const jwt = require('jsonwebtoken');
const { WorkspaceMembership } = require('../models/workspace');

const server = http.createServer();
const io = new Server(server);

const pubClient = new Redis(process.env.REDIS_URL);
const subClient = pubClient.duplicate();
io.adapter(createAdapter(pubClient, subClient));

const workspaceNsp = io.of(/^\/workspaces\/[a-zA-Z0-9_-]+$/);

workspaceNsp.use(async (socket, next) => {
  const token = socket.handshake.auth.token;
  if (!token) return next(new Error('Authentication token required'));

  try {
    const decoded = jwt.verify(token, process.env.JWT_SECRET);
    socket.user = decoded;

    const workspaceId = socket.nsp.name.split('/')[2];

    // Enforce object-level authorization on workspace namespace connection
    const isMember = await WorkspaceMembership.checkAccess(decoded.userId, workspaceId);
    if (!isMember) {
      return next(new Error('Access denied: not a member of this workspace'));
    }

    next();
  } catch (err) {
    next(new Error('Authentication or authorization failure'));
  }
});

workspaceNsp.on('connection', (socket) => {
  const workspaceId = socket.nsp.name.split('/')[2];

  socket.on('request_board_sync', async () => {
    const boardData = await fetchWorkspaceBoards(workspaceId);
    socket.emit('board_state', boardData);
  });
});

server.listen(4001);
